set-variable.value:
@{
            try {
              var b = context.Request.Body.As<JObject>(preserveContent: true);
              var s = b["stream"];
              return (s != null && s.Type == JTokenType.Boolean && (bool)s) ? "true" : "false";
            } catch (Exception) { return "false"; }
        }

@{
            if (context.Request.Method != "POST") { return "empty"; }
            try {
              var b = context.Request.Body.As<JObject>(preserveContent: true);
              var msgs = b == null ? null : b["messages"] as JArray;
              if (msgs == null) { return "invalid"; }
              int userLen = 0; int docs = 0; int docLen = 0;
              foreach (var m in msgs) {
                string role = (string)m["role"];
                var content = m["content"];
                string t = "";
                if (content != null && content.Type != JTokenType.Null) {
                  if (content.Type == JTokenType.String) { t = (string)content; }
                  else {
                    var parts = content as JArray;
                    if (parts == null) { return "invalid"; }
                    var text = new System.Text.StringBuilder();
                    foreach (var p in parts) {
                      var partText = p["text"];
                      if (partText != null && partText.Type == JTokenType.String) { text.Append((string)partText).Append("\n"); }
                    }
                    t = text.ToString();
                  }
                }
                if (t.Trim().Length == 0) { continue; }
                if (role == "user") { userLen += t.Length + (userLen == 0 ? 0 : 1); }
                else if (role == "tool") { docs++; docLen += t.Length; if (t.Length > 10000) { return "oversized"; } }
              }
              if (userLen > 10000 || docs > 5 || docLen > 10000) { return "oversized"; }
              if (userLen == 0 && docs > 0) { return "invalid"; }
              return (userLen == 0 && docs == 0) ? "empty" : "ok";
            } catch (Exception) { return "invalid"; }
        }

@{
                var b = context.Request.Body.As<JObject>(preserveContent: true);
                var user = new System.Text.StringBuilder();
                var docs = new JArray();
                var msgs = b["messages"] as JArray;
                if (msgs == null) { throw new Exception("messages"); }
                foreach (var m in msgs) {
                  string role = (string)m["role"];
                  var content = m["content"];
                  string t = "";
                  if (content != null && content.Type != JTokenType.Null) {
                    if (content.Type == JTokenType.String) { t = (string)content; }
                    else {
                      var parts = content as JArray;
                      if (parts == null) { throw new Exception("content"); }
                      var text = new System.Text.StringBuilder();
                      foreach (var p in parts) {
                        var partText = p["text"];
                        if (partText != null && partText.Type == JTokenType.String) { text.Append((string)partText).Append("\n"); }
                      }
                      t = text.ToString();
                    }
                  }
                  if (t.Trim().Length == 0) { continue; }
                  if (role == "user") { if (user.Length > 0) { user.Append("\n"); } user.Append(t); }
                  else if (role == "tool") { docs.Add(t); }
                }
                string u = user.ToString();
                return new JObject(new JProperty("userPrompt", u), new JProperty("documents", docs)).ToString(Newtonsoft.Json.Formatting.None);
            }

@{
                var b = context.Request.Body.As<JObject>(preserveContent: true);
                var sb = new System.Text.StringBuilder();
                var msgs = b["messages"] as JArray;
                if (msgs == null) { throw new Exception("messages"); }
                foreach (var m in msgs) {
                  if ((string)m["role"] != "user") { continue; }
                  var content = m["content"];
                  string t = "";
                  if (content != null && content.Type != JTokenType.Null) {
                    if (content.Type == JTokenType.String) { t = (string)content; }
                    else {
                      var parts = content as JArray;
                      if (parts == null) { throw new Exception("content"); }
                      var text = new System.Text.StringBuilder();
                      foreach (var p in parts) {
                        var partText = p["text"];
                        if (partText != null && partText.Type == JTokenType.String) { text.Append((string)partText).Append("\n"); }
                      }
                      t = text.ToString();
                    }
                  }
                  if (t.Trim().Length == 0) { continue; }
                  if (sb.Length > 0) { sb.Append("\n"); } sb.Append(t);
                }
                if (sb.Length == 0) { return ""; }
                return new JObject(new JProperty("text", sb.ToString()), new JProperty("categories", new JArray("Hate", "SelfHarm", "Sexual", "Violence")), new JProperty("outputType", "FourSeverityLevels")).ToString(Newtonsoft.Json.Formatting.None);
            }

@{
                try {
                  var r = context.Variables.GetValueOrDefault<IResponse>("rp-shield-resp");
                  if (r == null) { return "null"; }
                  int s = r.StatusCode;
                  if (s == 200) {
                    var j = r.Body.As<JObject>();
                    var up = j == null ? null : j["userPromptAnalysis"] as JObject;
                    if (up == null) { return "invalid"; }
                    var ua = up["attackDetected"];
                    if (ua == null || ua.Type != JTokenType.Boolean) { return "invalid"; }
                    bool a = (bool)ua;
                    int expected = ((JArray)JObject.Parse((string)context.Variables["rp-cs-shield-body"])["documents"]).Count;
                    var docs = j["documentsAnalysis"] as JArray;
                    if ((docs == null ? 0 : docs.Count) != expected) { return "invalid"; }
                    if (docs != null) {
                      foreach (var d in docs) {
                        var x = d["attackDetected"];
                        if (x == null || x.Type != JTokenType.Boolean) { return "invalid"; }
                        if ((bool)x) { a = true; }
                      }
                    }
                    return a ? "attack" : "clean";
                  }

                  if (s == 401 || s == 403) { return "auth"; }
                  if (s == 408 || s == 429 || (s >= 500 && s <= 599)) { return "dependency"; }
                  return "config";
                } catch (Exception) { return "invalid"; }
            }

@{
                if (((string)context.Variables["rp-cs-analyze-body"]).Length == 0) { return "ok::0"; }

                try {
                  var r = context.Variables.GetValueOrDefault<IResponse>("rp-analyze-resp");
                  if (r == null) { return "null"; }
                  int s = r.StatusCode;
                  if (s == 200) {
                    var j = r.Body.As<JObject>();
                    var items = j == null ? null : j["categoriesAnalysis"] as JArray;
                    if (items == null) { return "invalid"; }
                    var want = new System.Collections.Generic.List<string> { "Hate", "SelfHarm", "Sexual", "Violence" };
                    string cat = ""; int sev = 0;
                    foreach (var i in items) {
                      string c = (string)i["category"]; var sv = i["severity"];
                      if (c == null || sv == null || sv.Type != JTokenType.Integer || !want.Contains(c)) { return "invalid"; }
                      want.Remove(c);
                      if ((int)sv > sev) { cat = c; sev = (int)sv; }
                    }
                    if (want.Count != 0) { return "invalid"; }
                    return "ok:" + cat + ":" + sev.ToString();
                  }

                  if (s == 401 || s == 403) { return "auth"; }
                  if (s == 408 || s == 429 || (s >= 500 && s <= 599)) { return "dependency"; }
                  return "config";
                } catch (Exception) { return "invalid"; }
            }

@{
                string s = (string)context.Variables["rp-shield-result"];
                string a = (string)context.Variables["rp-analyze-result"];
                bool over = a.StartsWith("ok:") && int.Parse(a.Split(':')[2]) >= {severity-threshold};
                if (s == "attack" || over) { return "block"; }
                if (!context.Variables.ContainsKey("rp-cs-token")) { return "error"; }
                bool sOk = s == "clean"; bool aOk = a.StartsWith("ok:");
                if (sOk && aOk) { return "allow"; }
                if ((sOk || s == "dependency") && (aOk || a == "dependency")) {
                  return ((string)context.Variables["rp-safety-mode"]) == "regulated" ? "error" : "allowed_on_safety_error";
                }
                return "error";
            }
